/* Loading overlay for GameChanger import */
.loading-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba\(0, 0, 0, 0.8\);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2000;
}

.loading-spinner {
  background: var\(--bg-secondary\);
  padding: 2rem;
  border-radius: 12px;
  text-align: center;
  min-width: 250px;
}

.loading-spinner p {
  color: var\(--text-primary\);
  margin-top: 1rem;
  font-size: 1rem;
}

.spinner {
  width: 50px;
  height: 50px;
  margin: 0 auto;
  border: 4px solid var\(--border-color\);
  border-top-color: var\(--primary-color\);
  border-radius: 50%;
  animation: spin 1s linear infinite;
}

@keyframes spin {
  to { transform: rotate\(360deg\); }
}
EOF)

